import {analyze} from './analysis.js';
const $=id=>document.getElementById(id);
const topics={
 everyday:[['Candy','What makes a childhood favorite so memorable?'],['Polar bears','What could we learn from life in an extreme environment?'],['Rainy days','Tell a story about finding something good in a gloomy day.'],['Coffee','Explain the ritual behind an everyday drink.'],['A favorite book','Share one idea that stayed with you.'],['Bicycles','Why does a simple invention make such a difference?'],['Street food','Take your audience on a tour of your favorite flavors.'],['Houseplants','What can caring for something small teach us?'],['Board games','What makes a game worth playing again?'],['Music','Describe a song through the memory it brings back.'],['The ocean','Explain what fascinates you about the sea.'],['A perfect weekend','Walk us through your ideal way to recharge.']],
 discovery:[['The Mpemba effect','Research when warmer water may freeze sooner than cooler water. Explain the conditions and the uncertainty.','Mpemba effect'],['The doorway effect','Research why walking into a new room can affect recall. Explain an experiment and its limits.','doorway effect memory'],['The cocktail party effect','How do we attend to one voice in a crowded room? Research a possible explanation.','cocktail party effect auditory attention'],['Slime mold navigation','Research how slime molds form networks. Explain what the findings do and do not show.','Physarum network formation'],['The rubber hand illusion','Research how a simple illusion changes our sense of body ownership.','rubber hand illusion'],['Sonoluminescence','Research how collapsing bubbles can emit light. Explain what remains uncertain.','sonoluminescence'],['The Leidenfrost effect','Research why a droplet can glide over a very hot surface.','Leidenfrost effect'],['The missing satellite problem','Research the gap between predicted and observed small satellite galaxies.','missing satellites problem']],
 argument:[['What is one policy you would enact if you were president?','Explain your proposal, acknowledge a tradeoff, and consider an objection.'],['What makes a good leader?','Choose one quality and defend it with a concrete example.'],['Should schools start later?','Make a case, acknowledge a tradeoff, and respond to an objection.'],['Is talent or practice more important?','Choose your position and explain the strongest reason for it.'],['Should everyone learn a musical instrument?','Build an argument with a clear claim, example, and conclusion.'],['Is competition good for creativity?','Defend your view while considering the other side.'],['Should a four-day workweek be the norm?','Explain a benefit, a cost, and how you would weigh them.'],['Would you rather explore space or the ocean?','Choose where to focus and support your argument.']]
};
let mode='everyday',duration=60,phase='idle',topicIndex=0,stream,recorder,recognition,clock,started=0,seconds=0,url,finalText='',interim='',chunks=[],recognitionFailed=false,recognitionRetries=0,run=0;
const Recognition=window.SpeechRecognition||window.webkitSpeechRecognition;
function time(n){return `${Math.floor(n/60)}:${String(n%60).padStart(2,'0')}`;}
function topicChange(random=true){if(phase==='recording'||phase==='starting'||phase==='stopping')return;const list=topics[mode];topicIndex=random?(topicIndex+1+Math.floor(Math.random()*(list.length-1)))%list.length:0;const [title,prompt,query]=list[topicIndex];$('topic').textContent=title;$('prompt').textContent=prompt;$('topic-category').textContent={everyday:'EVERYDAY THINGS',discovery:'CURIOUS DISCOVERIES',argument:'MAKE YOUR CASE'}[mode];$('research').hidden=mode!=='discovery';$('notes').value='';if(query)$('research-link').href='https://scholar.google.com/scholar?q='+encodeURIComponent(query);}
function lock(on){document.querySelectorAll('fieldset input').forEach(el=>el.disabled=on);$('shuffle').disabled=on;$('rescore').disabled=on;}
function renderFeedback(){const result=analyze($('transcript').value,seconds,mode!=='argument');$('score').textContent=result.score??'—';$('score-label').textContent=mode==='argument'?'Descriptive feedback for arguments':result.score===null?'Not enough speech to score':result.score>=80?'A steady foundation':result.score>=60?'Keep building your rhythm':'A useful starting point';$('pace').textContent=result.valid?result.pace:'—';$('fillers').textContent=result.fillers;$('repeats').textContent=result.repeats;$('elapsed').textContent=seconds.toFixed(1);$('coach').textContent=result.tips.join(' ');const counts={};result.matches.forEach(x=>counts[x]=(counts[x]||0)+1);$('detected').textContent=Object.keys(counts).length?'Review these candidates: '+Object.entries(counts).map(([k,v])=>`${k} × ${v}`).join(' · '):'No filler candidates found in this transcript. Recognition may omit hesitations.';}
function finishReview(){phase='review';lock(false);$('record').disabled=false;$('record').innerHTML='<span>●</span> Practice again';$('status').textContent='Round complete';$('empty').hidden=true;$('review').hidden=false;$('transcript').value=(finalText+' '+interim).trim();renderFeedback();$('message').textContent=recognitionFailed?'Live transcription was unavailable or interrupted. Replay your recording and correct or enter the transcript below.':'Your round is ready. Listen back and review your transcript.';}
function startRecognition(token){if(!Recognition){recognitionFailed=true;return;}const current=new Recognition();recognition=current;current.lang='en-US';current.continuous=true;current.interimResults=true;current.onresult=e=>{if(token!==run)return;interim='';for(let i=e.resultIndex;i<e.results.length;i++){if(e.results[i].isFinal)finalText+=e.results[i][0].transcript+' ';else interim+=e.results[i][0].transcript;}};current.onerror=e=>{if(token!==run)return;if(e.error!=='no-speech'&&e.error!=='aborted'){recognitionFailed=true;$('message').textContent='Transcription interrupted. Audio recording continues; you can enter a transcript afterward.';}};current.onend=()=>{if(token===run&&phase==='recording'&&!recognitionFailed&&recognitionRetries++<8){interim='';startRecognition(token);}};try{current.start();}catch{recognitionFailed=true;}}
async function start(){if(!navigator.mediaDevices?.getUserMedia||!window.MediaRecorder){$('message').textContent='Recording is not supported here. Open this page over HTTPS or localhost in a browser with microphone recording support.';return;}phase='starting';lock(true);$('record').disabled=true;$('message').textContent='Allow microphone access to begin your round.';let localStream;try{localStream=await navigator.mediaDevices.getUserMedia({audio:true});stream=localStream;const mime=['audio/webm;codecs=opus','audio/mp4','audio/webm'].find(x=>MediaRecorder.isTypeSupported(x));recorder=new MediaRecorder(stream,mime?{mimeType:mime}:undefined);run++;const token=run;chunks=[];finalText='';interim='';seconds=0;recognitionFailed=false;recognitionRetries=0;recorder.ondataavailable=e=>{if(e.data.size)chunks.push(e.data);};recorder.onstop=()=>{stream?.getTracks().forEach(t=>t.stop());if(url)URL.revokeObjectURL(url);const blob=new Blob(chunks,{type:recorder.mimeType});url=URL.createObjectURL(blob);$('audio').src=url;$('download').href=url;$('download').download=`speakwell-${new Date().toISOString().slice(0,10)}.${blob.type.includes('mp4')?'m4a':'webm'}`;$('audio-wrap').hidden=!blob.size;setTimeout(()=>{if(token!==run)return;recognition?.abort();finishReview();},700);};recorder.onerror=()=>{recognitionFailed=true;stop();};stream.getAudioTracks()[0].onended=()=>{if(phase==='recording')stop();};recorder.start(200);started=performance.now();phase='recording';$('review').hidden=true;$('empty').hidden=false;$('audio').pause();$('record').disabled=false;$('record').textContent='■  Finish recording';$('status').textContent='Recording your voice';$('wave').classList.add('active');$('message').textContent='Take your time. The recording stops automatically.';startRecognition(token);clock=setInterval(()=>{seconds=(performance.now()-started)/1000;$('timer').textContent=time(Math.max(0,Math.ceil(duration-seconds)));$('progress').value=Math.min(duration,seconds);if(seconds>=duration)stop();},100);}catch(error){localStream?.getTracks().forEach(t=>t.stop());phase='idle';lock(false);$('record').disabled=false;$('message').textContent=error.name==='NotAllowedError'?'Microphone access was denied. Allow it in your browser settings, then try again.':error.name==='NotFoundError'?'No microphone was found. Connect one and try again.':'Could not start recording. Check your microphone and try again.';}}
function stop(){if(phase!=='recording')return;phase='stopping';clearInterval(clock);seconds=(performance.now()-started)/1000;$('record').disabled=true;$('status').textContent='Preparing your feedback';$('wave').classList.remove('active');try{recognition?.stop();}catch{}if(recorder?.state!=='inactive')recorder.stop();else finishReview();}
$('record').onclick=()=>phase==='recording'?stop():start();$('shuffle').onclick=()=>topicChange();$('rescore').onclick=renderFeedback;
document.querySelectorAll('input[name=mode]').forEach(input=>input.onchange=()=>{mode=input.value;document.querySelectorAll('.mode').forEach(el=>el.classList.toggle('selected',el.contains(input)));topicChange(false);if(phase==='review'){phase='idle';$('review').hidden=true;$('empty').hidden=false;}});
document.querySelectorAll('input[name=duration]').forEach(input=>input.onchange=()=>{duration=Number(input.value);$('timer').textContent=time(duration);$('progress').max=duration;$('progress').value=0;});
if(!Recognition)$('message').textContent='Live transcription is unavailable in this browser. Recording still works; add a transcript afterward.';
window.addEventListener('pagehide',()=>{clearInterval(clock);recognition?.abort();stream?.getTracks().forEach(t=>t.stop());if(url)URL.revokeObjectURL(url);});
const context=document.modelContext;
if(context?.registerTool){try{Promise.resolve(context.registerTool({name:'generate_speaking_topic',title:'Generate a speaking topic',description:'Choose a challenge mode and generate a topic in the practice room. Does not start microphone recording.',inputSchema:{type:'object',properties:{mode:{type:'string',enum:['everyday','discovery','argument']}},required:['mode'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute(input){if(!input||!Object.hasOwn(topics,input.mode))throw new Error('Unknown challenge mode');if(['starting','recording','stopping'].includes(phase))throw new Error('Finish the current recording first');const radio=document.querySelector(`input[name=mode][value="${input.mode}"]`);radio.checked=true;radio.dispatchEvent(new Event('change'));topicChange();return {mode,topic:$('topic').textContent,prompt:$('prompt').textContent};}})).catch(()=>{});}catch{}}
